mapper.select:
SELECT *, count(*) OVER()::integer AS total FROM credential_handles
WHERE organization_id = #{organizationId}
ORDER BY created_at DESC, id DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE credential_handles SET name = COALESCE(#{name}, name), status = COALESCE(#{status}, status),
  metadata = COALESCE(#{metadata, typeHandler=com.kross.support.JsonbTypeHandler}, metadata), updated_at = now()
WHERE organization_id = #{organizationId} AND id = #{id}

mapper.select:
SELECT *, count(*) OVER()::integer AS total FROM model_profiles
WHERE organization_id = #{organizationId}
ORDER BY created_at DESC, id DESC LIMIT #{limit} OFFSET #{offset}
